/**
 * @file src/components/features/ProductGrid.tsx
 * @description Grid de produtos com filtro de categoria.
 * Client Component — estado do filtro é local (sem URL).
 *
 * Recebe array de SKUs → ProductCard busca os dados no config.
 * Para alterar produtos exibidos → edite os SKUs na page.tsx.
 */
'use client';

import { useState, useMemo } from 'react';
import { ProductCard }      from './ProductCard';
import { CategoryFilter }   from './CategoryFilter';
import { getProductBySku, type ProductCategory } from '@/constants/site-config';

type ProductGridProps = {
  skus: string[];
};

export function ProductGrid({ skus }: ProductGridProps) {
  const [activeCategory, setActiveCategory] = useState<ProductCategory | 'todos'>('todos');

  // Filtra os SKUs pela categoria selecionada
  const filteredSkus = useMemo(() => {
    if (activeCategory === 'todos') return skus;
    return skus.filter(sku => {
      const product = getProductBySku(sku);
      return product?.category === activeCategory;
    });
  }, [skus, activeCategory]);

  return (
    <div>
      {/* Filtros */}
      <div className="mb-8 flex flex-col sm:flex-row sm:items-center
                      justify-between gap-4">
        <CategoryFilter
          current={activeCategory}
          onChange={setActiveCategory}
        />
        <p
          className="font-mono text-xs text-brand-muted"
          aria-live="polite"
          aria-atomic="true"
        >
          {filteredSkus.length} produto{filteredSkus.length !== 1 ? 's' : ''}
          {activeCategory !== 'todos' && ` em ${activeCategory}`}
        </p>
      </div>

      {/* Grid */}
      {filteredSkus.length > 0 ? (
        <ul
          className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6"
          role="list"
          aria-label={`${filteredSkus.length} produtos`}
        >
          {filteredSkus.map((sku, i) => (
            <li
              key={sku}
              role="listitem"
              style={{ animationDelay: `${i * 60}ms` }}
              className="animate-fade-up"
            >
              <ProductCard sku={sku} className="h-full" />
            </li>
          ))}
        </ul>
      ) : (
        <EmptyState category={activeCategory} onReset={() => setActiveCategory('todos')} />
      )}
    </div>
  );
}

// ── Estado vazio ─────────────────────────────────────────────────
function EmptyState({
  category,
  onReset,
}: {
  category: string;
  onReset:  () => void;
}) {
  return (
    <div
      role="status"
      aria-live="polite"
      className="flex flex-col items-center justify-center py-24 gap-4 text-center"
    >
      <div
        className="font-mono text-6xl text-brand-muted/20 select-none"
        aria-hidden="true"
      >
        [ ]
      </div>
      <p className="font-display text-brand-muted text-sm tracking-widest uppercase">
        Nenhum produto em &quot;{category}&quot;
      </p>
      <button
        onClick={onReset}
        className="font-mono text-xs text-brand-primary underline
                   underline-offset-4 hover:text-brand-neon-dim transition-colors"
      >
        Ver todos os produtos
      </button>
    </div>
  );
}
